import{_ as i,o as e,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"2019-11-19 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-11-19 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-11-19T00:00:00.000Z","updated":"2019-11-26T00:00:00.000Z","tags":["Ceph","分布式存储","HPN","用户空间驱动程序","内核性能"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-11-19_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-11-19_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2019/2019-11-19_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function s(n,l,a,_,p,g){return e(),t("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年11月19日</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议主题</strong>：</p><p>本次会议主要讨论了Ceph分布式存储项目的研发进展、视频会议字幕翻译工作以及其他相关议题。</p><p><strong>关键细节</strong>：</p><ul><li><strong>Ceph研发进展</strong>： <ul><li>开始审查Readex Air项目，并着手查看Tamez项目。</li><li>讨论HPN（高性能网络）的需求和准备。</li><li>英国树（British tree）的初步实现正在进行中。</li><li>多个补丁被接受，包括来自Crimson的补丁和针对Hag的解决方案。</li><li>探讨引入第三个值优化状态转换的开销。</li><li>讨论是否将用户空间驱动程序作为Crimson和Sister的主要后端。</li></ul></li><li><strong>视频会议字幕翻译</strong>： <ul><li>正在将英文字幕翻译为中文。</li><li>已完成部分工作，计划下周继续。</li></ul></li><li><strong>其他</strong>： <ul><li>有成员计划请假。</li><li>有成员正在准备下周的代码审查。</li></ul></li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li>Ceph研发中的HPN需求。</li><li>用户空间驱动程序的优先级。</li><li>视频会议字幕翻译进展。</li><li>代码审查准备。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>继续推进Ceph研发工作，特别是HPN需求和用户空间驱动程序的讨论。</li><li>继续进行视频会议字幕翻译工作。</li><li>准备下周的代码审查。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Ceph研发团队继续推进相关研发工作。</li><li>视频会议字幕翻译团队继续翻译工作。</li><li>准备下周的代码审查。</li></ul><p><strong>其他</strong>：</p><ul><li>会议中提到的关键词包括： <ul><li>HPN (High Performance Network)</li><li>British tree</li><li>Ceph</li><li>POSIX</li><li>IPC (Instructions Per Cycle)</li><li>Reactor</li><li>User space drivers</li></ul></li></ul><p><strong>备注</strong>：</p><ul><li>本次会议纪要仅供参考，具体内容以会议录音或录音整理为准。</li></ul>',17)])])}const d=i(o,[["render",s]]);export{S as __pageData,d as default};
